float novaBluePhase(uint2 pixel, uint frame)
{
    uint index = (pixel.y & 31) * 32 + (pixel.x & 31);
    uint rank = (novaBlueRank[index / 2] >> ((index & 1) * 16)) & 1023;
    return frac((rank + .5) / 1024 + frame * .61803398875) * 6.28318531;
}
#define NOVA_RASTER_AA 1
#ifndef NOVA_MATERIAL_SHEEN
#define NOVA_MATERIAL_SHEEN
// Directional albedo of the Charlie distribution with Ashikhmin visibility.
// Integrated using 4096 importance-sampled half vectors at each grid coordinate.
static const uint sheenAlbedoTable[64] = {
    0x062effffu, 0x00000001u, 0x00000000u, 0x00000000u, 0x1559ffffu, 0x00000104u, 0x00000000u, 0x00000000u,
    0x5bafffffu, 0x040a162eu, 0x00000102u, 0x00000000u, 0x7abbffffu, 0x131f324fu, 0x0103060bu, 0x00000001u,
    0x83b4fdffu, 0x2231455fu, 0x060a1018u, 0x00010203u, 0x84aae1ffu, 0x2f3d5067u, 0x0d121a23u, 0x01020508u,
    0x82a1cbffu, 0x37455569u, 0x141a222cu, 0x0306090eu, 0x7e98bbf9u, 0x3e4a596au, 0x1a212933u, 0x060a0f14u,
    0x7b91aee3u, 0x424d5a69u, 0x20272f38u, 0x0a0f141au, 0x788ba4d2u, 0x454f5b68u, 0x252c333cu, 0x0e13191fu,
    0x75869dc5u, 0x47515b67u, 0x2930373fu, 0x13181d23u, 0x738296bau, 0x49515b66u, 0x2d333a41u, 0x171c2127u,
    0x707f91b2u, 0x4a525b65u, 0x30363c43u, 0x1b20252au, 0x6f7c8dabu, 0x4b525b64u, 0x32383e44u, 0x1e23282du,
    0x6d7989a6u, 0x4c535a63u, 0x353a3f45u, 0x21262b2fu, 0x6c7786a1u, 0x4c535a62u, 0x363b4146u, 0x24282d32u,
};
float sheenAlbedoTexel(uint2 position)
{
    uint index = position.y * 16 + position.x;
    return float((sheenAlbedoTable[index >> 2] >> ((index & 3u) * 8)) & 255u) / 255;
}
float sheenAlbedo(float nv, float roughness)
{
    float2 p = saturate(float2(nv, roughness)) * 15;
    uint2 a = uint2(p), b = min(a + 1, 15);
    float2 f = frac(p);
    return lerp(lerp(sheenAlbedoTexel(a), sheenAlbedoTexel(uint2(b.x, a.y)), f.x),
                lerp(sheenAlbedoTexel(uint2(a.x, b.y)), sheenAlbedoTexel(b), f.x), f.y);
}
float3 sheenLayer(float4 sheen, float3 n, float3 v, float3 l, float3 baseBrdf)
{
#if defined(NOVA_DISABLE_SHEEN)
    return baseBrdf;
#else
    if (!any(sheen.rgb > 0))
        return baseBrdf;
    float nv = saturate(dot(n, v)), nl = saturate(dot(n, l));
    if (nv <= 0 || nl <= 0)
        return baseBrdf;
    float nvAlbedo = sheenAlbedo(nv, sheen.a), nlAlbedo = sheenAlbedo(nl, sheen.a);
    float energy = max(sheen.r, max(sheen.g, sheen.b));
    float baseWeight = 1 - energy * max(nvAlbedo, nlAlbedo);
    float invAlpha = 1 / max(.0025, sheen.a * sheen.a);
    float nh = saturate(dot(n, normalize(v + l)));
    float distribution = (2 + invAlpha) * pow(saturate(1 - nh * nh), invAlpha * .5) / 6.283185307;
    float visibility = 1 / max(4 * (nv + nl - nv * nl), 1e-6);
    return baseBrdf * baseWeight + sheen.rgb * (distribution * visibility);
#endif
}
#endif

#ifndef NOVA_MATERIAL_IRIDESCENCE
#define NOVA_MATERIAL_IRIDESCENCE
float filmBaseReflectance(float ior)
{
    float amplitude = (ior - 1) / (ior + 1);
    return amplitude * amplitude;
}
float3 filmInterference(float3 front, float3 back, float3 phase)
{
    float3 crossTerm = 2 * front * back * cos(phase);
    float3 product = front * back;
    return saturate((front * front + back * back + crossTerm) /
                    max(1 + product * product + crossTerm, 1e-6));
}
float3 thinFilmReflectance(float cosine, float3 baseF0, float filmIor, float thickness)
{
    float ct1 = saturate(cosine);
    float sinSq = 1 - ct1 * ct1;
    float ct2 = sqrt(saturate(1 - sinSq / (filmIor * filmIor)));
    float3 baseAmplitude = sqrt(clamp(baseF0, 0, .9999));
    float3 substrateIor = (1 + baseAmplitude) / (1 - baseAmplitude);
    float3 ct3 = sqrt(saturate(1 - sinSq / (substrateIor * substrateIor)));

    // Signed Fresnel amplitudes retain the phase reversal at each interface.
    float amplitudeS = (ct1 - filmIor * ct2) / max(ct1 + filmIor * ct2, 1e-6);
    float amplitudeP = (filmIor * ct1 - ct2) / max(filmIor * ct1 + ct2, 1e-6);
    float3 amplitudeS2 = (filmIor * ct2 - substrateIor * ct3) / max(filmIor * ct2 + substrateIor * ct3, 1e-6);
    float3 amplitudeP2 = (substrateIor * ct2 - filmIor * ct3) / max(substrateIor * ct2 + filmIor * ct3, 1e-6);

    // Sample a small wavelength band per linear RGB channel. Averaging the
    // three samples avoids treating each channel as a monochromatic light.
    float phaseNumerator = 12.566370614 * filmIor * thickness * ct2;
    float3 wavelength = float3(610, 547, 462);
    float3 bandwidth = float3(36, 38, 29);
    float3 result = 0;
    [unroll] for (int i = -1; i <= 1; ++i)
    {
        float3 phase = phaseNumerator / (wavelength + bandwidth * i);
        result += filmInterference(amplitudeS, amplitudeS2, phase) +
                  filmInterference(amplitudeP, amplitudeP2, phase);
    }
    return result / 6;
}
float3 blendThinFilm(float3 ordinary, float cosine, float3 baseF0, float3 film)
{
    return film.x > 0 && film.z > 0
      ? lerp(ordinary, thinFilmReflectance(cosine, baseF0, film.y, film.z), film.x)
      : ordinary;
}
#endif

#ifndef NOVA_MATERIAL_ANISOTROPY
#define NOVA_MATERIAL_ANISOTROPY
float3 anisotropicBasis(float3 n)
{
    return normalize(cross(abs(n.y) < .999 ? float3(0, 1, 0) : float3(1, 0, 0), n));
}
float3 anisotropicTangent(float3 n, float3 tangent)
{
    float3 projected = tangent - n * dot(tangent, n);
    return dot(projected, projected) > 1e-10 ? normalize(projected) : anisotropicBasis(n);
}
float2 anisotropicRoughness(float roughness, float strength)
{
    float alpha = max(.0004, roughness * roughness);
    return float2(lerp(alpha, 1, strength * strength), alpha);
}
float3 anisotropicCoordinates(float3 direction, float3 n, float3 t)
{
    return float3(dot(direction, t), dot(direction, cross(n, t)), dot(direction, n));
}
float anisotropicD(float3 h, float3 n, float3 t, float2 alpha)
{
    float3 projected = anisotropicCoordinates(h, n, t);
    projected.xy /= alpha;
    float q = dot(projected, projected);
    return 1 / max(3.14159265 * alpha.x * alpha.y * q * q, 1e-12);
}
float anisotropicVisibility(float3 v, float3 l, float3 n, float3 t, float2 alpha)
{
    float3 vv = anisotropicCoordinates(v, n, t), ll = anisotropicCoordinates(l, n, t);
    float d = ll.z * length(float3(vv.xy * alpha, vv.z)) +
              vv.z * length(float3(ll.xy * alpha, ll.z));
    return .5 / max(d, 1e-6);
}
float3 anisotropicHalfVector(float2 randomSample, float3 n, float3 t, float2 alpha)
{
    float phi = 6.283185307 * randomSample.y;
    float radius = sqrt(randomSample.x / max(1 - randomSample.x, 1e-7));
    return normalize(n + radius * (t * (cos(phi) * alpha.x) + cross(n, t) * (sin(phi) * alpha.y)));
}
float3 anisotropicEnvironmentDirection(float3 n, float3 v, float3 t, float roughness, float strength)
{
    if (strength <= 0)
        return reflect(-v, n);
    float3 b = cross(n, t);
    float3 normal = anisotropicTangent(b, v);
    if (dot(normal, n) < 0)
        normal = -normal;
    float bend = 1 - pow(1 - strength * (1 - roughness), 4);
    normal = normalize(lerp(n, normal, bend));
    return normalize(lerp(reflect(-v, normal), normal, roughness * roughness));
}
#endif

